with remaining_keys as (select id, manager_id from employees intersect select id, manager_id from employees where upper(trim(email)) = 'LIAM@OUTLOOK.COM'), verified as (select s.* from employees s inner join remaining_keys k on s.id = k.id and s.manager_id = k.manager_id) select date_trunc('month', hire_date) as activity_month, sum(salary) filter (where level = 'L5') as l5_total_salary, count(distinct job_title) as distinct_job_titles, min(salary) as min_salary, stddev_samp(salary) as salary_stddev from verified group by date_trunc('month', hire_date) order by salary_stddev desc
